gDs(){return"\u0644\u0627 \u062a\u064f\u0631\u0633\u0644 \u0627\u0644\u0635\u0648\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u0631\u0633\u0644 \u0625\u0644\u064a\u0647\u0645."},
gCX(){return"\u0627\u0644\u0625\u0642\u0631\u0627\u0631 \u0628\u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645"},
gCY(){return"\u062a\u0645 \u0627\u0644\u0625\u0642\u0631\u0627\u0631 \u0628\u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645"},
gCZ(){return"\u062a\u0645 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u0625\u0642\u0631\u0627\u0631 \u0628\u0627\u0644\u0627\u0633\u062a\u0644\u0627\u0645"},
gDM(){return"\u0645\u0634\u0627\u0631\u0643\u0629 / \u0637\u0628\u0627\u0639\u0629"},
