gDk(){return"\u0645\u0641\u0642\u0648\u062f \u0645\u0646\u0630"},
gD0(){return"\u0627\u062a\u0635\u0627\u0644"},
gD2(){return"\u0628\u0644\u0627\u063a \u0628\u062d\u062b"},
gD3(){return"\u0646\u062f\u0627\u0621 \u0644\u0644\u0634\u0647\u0648\u062f"},
gD4(){return"\u0627\u062e\u062a\u0641\u0627\u0621 \u0645\u0642\u0644\u0642"},
gqD(){return"\u062c\u0627\u0631\u064d \u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u2014 \u064a\u064f\u0631\u062c\u0649 \u0627\u0644\u0627\u0646\u062a\u0638\u0627\u0631."},
gxO(){return"\u064a\u0648\u062c\u062f \u0628\u0627\u0644\u0641\u0639\u0644 \u0645\u0644\u0641 \u062a\u0645\u0647\u064a\u062f\u064a \u0644\u0647\u0630\u0627 \u0627\u0644\u0625\u062c\u0631\u0627\u0621."},
gxP(){return"\u0644\u0627 \u064a\u064f\u0643\u0634\u0641 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0633\u0631\u064a \u0627\u0644\u0637\u0648\u064a\u0644 \u0625\u0644\u0627 \u0644\u062d\u0638\u0629 \u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u062a\u0645\u0647\u064a\u062f\u064a\u060c \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0639\u0631\u0636\u0647 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649. \u0631\u0645\u0632 \u0627\u0644\u0645\u0644\u0641 \u0623\u0639\u0644\u0627\u0647 \u0647\u0648 \u0645\u0627 \u062a\u0637\u0644\u0628\u0647 \u0642\u0648\u0627\u062a \u0627\u0644\u0623\u0645\u0646."},
gMD(){return"\u0623\u064f\u0631\u0633\u0644 \u0628\u0627\u0644\u0641\u0639\u0644 \u2014 \u0627\u0646\u0638\u0631 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629 \u0623\u062f\u0646\u0627\u0647."},
gyj(){return"\u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0645\u062a\u0648\u0642\u0641. \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17\u060c \u0623\u0648 \u0623\u0631\u0633\u0644\u0647 \u0625\u0644\u0649 \u0648\u062d\u062f\u0629 \u0623\u062e\u0631\u0649 \u0645\u0646 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0623\u062f\u0646\u0627\u0647."},
gEa(){return"\u0623\u064f\u0646\u0634\u0626 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u062a\u0645\u0647\u064a\u062f\u064a \u0648\u0644\u0643\u0646\u0647 \u0644\u0645 \u064a\u064f\u0631\u0633\u0644"},
gE9(){return"\u0644\u0645 \u064a\u0635\u0644 \u0634\u064a\u0621 \u0628\u0639\u062f \u0625\u0644\u0649 \u0642\u0648\u0627\u062a \u0627\u0644\u0623\u0645\u0646. \u0623\u0631\u0633\u0644\u0647 \u0627\u0644\u0622\u0646\u060c \u0623\u0648 \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17 \u0648\u0623\u0639\u0637\u0647\u0645 \u0631\u0645\u0632 \u0627\u0644\u0645\u0644\u0641."},
gE5(){return"\u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0645\u062a\u0648\u0642\u0641"},
gE2(){return"\u0644\u0645 \u062a\u062a\u0633\u0644\u0645 \u0623\u064a \u0648\u062d\u062f\u0629 \u0647\u0630\u0627 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u062a\u0645\u0647\u064a\u062f\u064a. \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17 \u0627\u0644\u0622\u0646 \u2014 \u0641\u0647\u0648 \u0627\u0644\u0633\u0628\u064a\u0644 \u0627\u0644\u0623\u0643\u064a\u062f \u0627\u0644\u0648\u062d\u064a\u062f."},
E3(a){return"\u0627\u0644\u0633\u0628\u0628: "+a},
E4(a){return"\u0645\u062a\u0648\u0642\u0641 \u0645\u0646\u0630 "+a},
E1(a){return"\u0645\u062d\u0627\u0648\u0644\u0627\u062a \u0627\u0644\u0625\u0631\u0633\u0627\u0644: "+a},
gyk(){return"\u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0625\u0644\u0649 \u0648\u062d\u062f\u0629 \u0623\u062e\u0631\u0649"},
gEx(){return"\u0627\u062e\u062a\u0631 \u0648\u062d\u062f\u0629"},
gEy(){return"\u0644\u0627 \u062a\u0628\u064a\u0651\u0646 \u0647\u0630\u0647 \u0627\u0644\u0642\u0627\u0626\u0645\u0629 \u0645\u0627 \u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u0627\u0644\u0648\u062d\u062f\u0629 \u0645\u062a\u0635\u0644\u0629. \u0625\u0646 \u0644\u0645 \u062a\u0643\u0646 \u0643\u0630\u0644\u0643\u060c \u0633\u064a\u062e\u0628\u0631\u0643 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u064a\u0645\u0643\u0646\u0643 \u0627\u062e\u062a\u064a\u0627\u0631 \u0648\u062d\u062f\u0629 \u0623\u062e\u0631\u0649. \u064a\u0628\u0642\u0649 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17 \u0647\u0648 \u0627\u0644\u0633\u0628\u064a\u0644 \u0627\u0644\u0623\u0643\u064a\u062f."},
