gEv(){return"\u062c\u064f\u0631\u0650\u0651\u0628\u062a \u0645\u0646 \u0642\u0628\u0644 \u2014 \u062f\u0648\u0646 \u0631\u062f"},
guR(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0648\u062d\u062f\u0629 \u0645\u062a\u0627\u062d\u0629 \u0641\u064a \u0627\u0644\u062f\u0644\u064a\u0644. \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17."},
Mf(a){return"\u0623\u064f\u0631\u0633\u0644 \u0625\u0644\u0649 "+a+"."},
gH0(){return"\u0644\u0645 \u062a\u0639\u062f \u0645\u062a\u0635\u0644\u0627\u064b \u0628\u062d\u0633\u0627\u0628\u0643. \u064a\u064f\u0631\u062c\u0649 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0645\u0646 \u062c\u062f\u064a\u062f."},
gH2(){return"\u0645\u062e\u0635\u0635 \u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0644\u062b\u0642\u0629 \u0644\u062f\u0649 \u0647\u0630\u0627 \u0627\u0644\u0634\u062e\u0635 \u0627\u0644\u0645\u062d\u0645\u064a."},
gH4(){return"\u0647\u0630\u0647 \u0627\u0644\u0648\u062d\u062f\u0629 \u063a\u064a\u0631 \u0645\u062a\u0635\u0644\u0629 \u0628\u0640 Lyhanna. \u0627\u062e\u062a\u0631 \u0648\u062d\u062f\u0629 \u0623\u062e\u0631\u0649\u060c \u0623\u0648 \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17."},
gH3(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0644\u062f\u0649 \u0647\u0630\u0647 \u0627\u0644\u0648\u062d\u062f\u0629 \u0623\u064a \u0645\u0633\u062a\u0644\u0645 \u064a\u0645\u0643\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647. \u0627\u062e\u062a\u0631 \u0648\u062d\u062f\u0629 \u0623\u062e\u0631\u0649\u060c \u0623\u0648 \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17."},
gH_(){return"\u0644\u0645 \u064a\u0639\u062f \u0647\u0630\u0627 \u0627\u0644\u0645\u0644\u0641 \u0645\u062a\u0648\u0642\u0641\u0627\u064b. \u062d\u062f\u0651\u062b \u0627\u0644\u0635\u0641\u062d\u0629."},
gGY(){return"\u0633\u0628\u0642 \u0625\u0631\u0633\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u062a\u0645\u0647\u064a\u062f\u064a."},
gH1(){return"\u0644\u0627 \u064a\u062d\u0642 \u0644\u0643 \u0627\u0644\u0642\u064a\u0627\u0645 \u0628\u0630\u0644\u0643 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u0644\u0641."},
gGZ(){return"\u0627\u0644\u0645\u0644\u0641 \u063a\u064a\u0631 \u0645\u0648\u062c\u0648\u062f."},
gpR(){return"\u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0629"},
qa(a){return"\u0627\u0644\u0633\u0628\u0628 \u0627\u0644\u0630\u064a \u0630\u0643\u0631\u0647 \u0627\u0644\u062e\u0627\u062f\u0645: "+a},
gAL(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0639\u0627\u0645\u0644 \u062b\u0627\u0646\u064d \u0645\u0648\u062b\u0651\u0642 \u0645\u0633\u062c\u0651\u0644 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0641\u062a\u062d \u0623\u064a \u062e\u062a\u0645 \u0642\u0628\u0644 \u0625\u0639\u062f\u0627\u062f\u0647."},
gAN(){return"\u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0639\u0627\u0645\u0644\u0643 \u0627\u0644\u062b\u0627\u0646\u064a \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u062d\u0627\u0644\u064a\u064b\u0627. \u0623\u0639\u062f \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0623\u0648 \u062a\u062d\u0642\u0642 \u0645\u0646 \u0627\u062a\u0635\u0627\u0644\u0643."},
gAI(){return"\u0625\u0639\u062f\u0627\u062f \u0627\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u062b\u0627\u0646\u064a"},
gAK(){return"\u0647\u0644 \u0641\u0642\u062f\u062a \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629\u061f"},
gAH(){return"\u062a\u0623\u0643\u064a\u062f"},
gtH(){return"\u062a\u0645\u0651 \u0631\u0641\u0636 \u0627\u0644\u0631\u0645\u0632. \u064a\u062a\u063a\u064a\u0651\u0631 \u0643\u0644 30 \u062b\u0627\u0646\u064a\u0629 \u2014 \u0623\u062f\u062e\u0644 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0645\u0639\u0631\u0648\u0636 \u0627\u0644\u0622\u0646."},
gAM(){return"\u064a\u062a\u0637\u0644\u0651\u0628 \u0641\u062a\u062d \u0627\u0644\u0623\u062e\u062a\u0627\u0645 \u0639\u0627\u0645\u0644\u064b\u0627 \u062b\u0627\u0646\u064a\u064b\u0627 \u062a\u0645\u0651 \u0627\u0644\u062a\u062d\u0642\u0642 \u0645\u0646\u0647 \u0642\u0628\u0644 \u0623\u0642\u0644 \u0645\u0646 15 \u062f\u0642\u064a\u0642\u0629."},
gpJ(){return"\u0639\u0627\u0645\u0644\u064a \u0627\u0644\u062b\u0627\u0646\u064a"},
grI(){return"\u0645\u0637\u0644\u0648\u0628 \u0644\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u062d\u0633\u0651\u0627\u0633\u0629"},
gJO(){return"\u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0627\u0644\u0642\u0648\u064a \u0645\u064f\u0641\u0639\u0651\u0644 \u0644\u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629"},
gJP(){return"\u0627\u0644\u062a\u0635\u062f\u064a\u0642 \u0627\u0644\u0642\u0648\u064a \u063a\u064a\u0631 \u0645\u064f\u0641\u0639\u0651\u0644 \u0644\u0647\u0630\u0647 \u0627\u0644\u062c\u0644\u0633\u0629"},
JR(a){return"\u062a\u0645\u0651 \u0627\u0644\u062a\u062d\u0642\u0642 \u0641\u064a "+a},
gx9(){return"\u0627\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u062b\u0627\u0646\u064a \u0641\u0639\u0651\u0627\u0644"},
gJw(){return"\u0644\u0647\u0630\u0627 \u0627\u0644\u062d\u0633\u0627\u0628 \u0639\u0627\u0645\u0644 \u062b\u0627\u0646\u064d \u0645\u0648\u062b\u0651\u0642. \u064a\u064f\u0637\u0644\u0628 \u0631\u0645\u0632\u0647 \u0639\u0646\u062f \u0625\u062c\u0631\u0627\u0621 \u062d\u0633\u0651\u0627\u0633 \u2014 \u0641\u062a\u062d \u0627\u0644\u0623\u062d\u0631\u0627\u0632 \u0623\u0648 \u0627\u0644\u0645\u0631\u0627\u0642\u0628 \u0627\u0644\u062a\u0642\u0646\u064a."},
gJJ(){return"\u0625\u0632\u0627\u0644\u0629 \u0647\u0630\u0627 \u0627\u0644\u0639\u0627\u0645\u0644"},
gJK(){return"\u063a\u064a\u0631 \u0645\u062a\u0627\u062d \u0647\u0646\u0627: \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0639\u0627\u0645\u0644 \u0627\u0644\u0645\u0648\u062b\u0651\u0642 \u0627\u0644\u0648\u062d\u064a\u062f \u0633\u062a\u063a\u0644\u0642 \u0641\u0648\u0631\u064b\u0627 \u0643\u0644 \u0627\u0644\u0623\u062e\u062a\u0627\u0645 \u0627\u0644\u062a\u064a \u064a\u0645\u0643\u0646\u0643 \u0641\u062a\u062d\u0647\u0627."},
gJH(){return"\u0625\u0639\u062f\u0627\u062f \u0644\u0645 \u064a\u064f\u0633\u062a\u0643\u0645\u0644"},
gJG(){return"\u062a\u0645\u0651 \u0625\u0646\u0634\u0627\u0621 \u0639\u0627\u0645\u0644 \u0644\u0643\u0646\u0651\u0647 \u0644\u0645 \u064a\u064f\u0648\u062b\u0651\u0642 \u0642\u0637\u0651. \u0623\u062f\u062e\u0644 \u0627\u0644\u0631\u0645\u0632 \u0645\u0646 \u062a\u0637\u0628\u064a\u0642 \u0627\u0644\u0645\u0635\u0627\u062f\u0642\u0629 \u0644\u0625\u0643\u0645\u0627\u0644\u0647\u060c \u0623\u0648 \u0623\u0632\u0644\u0647 \u0648\u0627\u0628\u062f\u0623 \u0645\u0646 \u062c\u062f\u064a\u062f."},
gJD(){return"\u0625\u0643\u0645\u0627\u0644 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f"},
gJI(){return"\u0625\u0632\u0627\u0644\u0629 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u063a\u064a\u0631 \u0627\u0644\u0645\u0643\u062a\u0645\u0644"},
gJL(){return"\u062a\u0645\u062a \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0639\u0627\u0645\u0644"},
gxc(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0639\u0627\u0645\u0644 \u062b\u0627\u0646\u064d"},
gJF(){return"\u0628\u062f\u0648\u0646 \u0639\u0627\u0645\u0644 \u062b\u0627\u0646\u064d\u060c \u064a\u0631\u0641\u0636 \u0627\u0644\u062e\u0627\u062f\u0645 \u0643\u0644 \u0642\u0631\u0627\u0631 \u0628\u0641\u062a\u062d \u0627\u0644\u0623\u062f\u0644\u0629 \u0627\u0644\u0645\u062e\u062a\u0648\u0645\u0629. \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u064a\u0633\u062a\u063a\u0631\u0642 \u062f\u0642\u064a\u0642\u0629 \u0648\u062a\u0637\u0628\u064a\u0642 \u0645\u0635\u0627\u062f\u0642\u0629."},
